window.AUTH=window.AUTH||{};window.AUTH["18-6943"]={"d":"18-6943","id":"2019/18-6943","n":"Banister v. Davis","briefs":[{"k":"petitioner","label":"Brief of petitioner Gregory Dean Banister","date":"2019-08-26","url":"https://www.supremecourt.gov/DocketPDF/18/18-6943/113696/20190826170522625_Banister%20Brief.pdf","side":"pet","n":73},{"k":"respondent","label":"Brief of respondent Lorie Davis, Director TDCJ","date":"2019-10-18","url":"https://www.supremecourt.gov/DocketPDF/18/18-6943/119505/20191018151857434_18-6943%20BRIEF%20FOR%20RESPONDENT.pdf","side":"res","n":0},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-10-25","url":"https://www.supremecourt.gov/DocketPDF/18/18-6943/120321/20191025143718109_18-6943bsacUnitedStates.pdf","side":"us","n":57},{"k":"reply","label":"Reply of petitioner Gregory Dean Banister","date":"2019-11-18","url":"https://www.supremecourt.gov/DocketPDF/18/18-6943/122785/20191118152715630_Banister%20-%20Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=92","tr":true,"items":[{"t":"case","label":"Anthony v. Cambra","cite":"236 F.3d 568","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/236/568/","by":{"0":"20"}},{"t":"case","label":"Archer v. Lynaugh","cite":"821 F.2d 1094","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/821/1094/","by":{"0":"26"}},{"t":"case","label":"Artuz v. Bennett","cite":"531 U.S. 4","y":2000,"id":"2000/99-1238","sc":1,"op":1,"sum":"The Court held that an application for state postconviction relief containing procedurally barred claims is properly filed within the meaning of the Antiterrorism and Effective Death Penalty Act of 1996.","sumSrc":"Oyez","by":{"0":"50","2":"28","3":"20"}},{"t":"case","label":"Bannister v. Armontrout","cite":"4 F.3d 1434","y":1993,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/4/1434/","op":3,"by":{"0":"45","2":"18","3":"4"}},{"t":"case","label":"Barefoot v. Estelle","cite":"463 U.S. 880","y":1983,"id":"1982/82-6080","sc":1,"sum":"The Supreme Court held that, in denying the stay of execution, the U.S. Court of Appeals for the Fifth Circuit necessarily examined the decision of the district court on the merits of the case. Although the Court of Appeals may not formally affirm the judgment of the lower court, the denial of the stay of execution serves the same purpose.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Blystone v. Horn","cite":"664 F.3d 397","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/664/397/","ar":1,"by":{"0":"16, 21, 28, 29, 37"}},{"t":"case","label":"Browder v. Director, Dep’t of Corrs. of Ill.","cite":"434 U.S. 257","y":1978,"id":"1977/76-5325","sc":1,"op":17,"sum":"The Court of Appeals lacked jurisdiction to review the original October 21 order because respondent's motion for a stay and an evidentiary hearing (in essence a motion for rehearing or reconsideration) was untimely under Rule 52 (b) or 59 and hence could not toll the running of the \"mandatory and jurisdictional\" 30-day time limit of Rule 4 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","2":"7, 19, 20","3":"3, 4, 7"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"op":1,"sum":"The Court held that although it was consistent with the Antiterrorism and Effective Death Penalty Act of 1996, the recall was a grave abuse of discretion.","sumSrc":"Oyez","by":{"0":"13, 19, 33, 34, 35, 36","2":"21, 23","3":"8"}},{"t":"case","label":"Castro v. United States","cite":"540 U.S. 375","y":2003,"id":"2003/02-6683","sc":1,"op":1,"sum":"The Court held that a federal court can recharacterize a motion as a first habeas corpus petition only if the court: (1) informs the litigant of the court's intent to recharacterize; (2) warns the litigant that this recharacterization means that any subsequent habeas corpus petition will be treated as a second petition; (3) gives the litigant an opportunity to withdraw or amend the motion.","sumSrc":"Oyez","by":{"0":"40, 41, 52","2":"20"}},{"t":"case","label":"Ching v. United States","cite":"298 F.3d 174","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/298/174/","by":{"0":"19, 20, 21","3":"17"}},{"t":"case","label":"Clark v. United States","cite":"764 F.3d 653","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/764/653/","by":{"0":"20"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Cullen v. Pinholster","cite":"563 U.S. 170","y":2011,"id":"2010/09-1088","sc":1,"sum":"The Court held that a federal court could not overturn a state criminal conviction on the basis of the facts the defendant could have alleged, but did not, in state court.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Exxon Shipping Co. v. Baker","cite":"554 U.S. 471","y":2008,"id":"2007/07-219","sc":1,"op":1,"sum":"On the second issue, a 5-4 majority held that judges are free to create remedies in maritime cases where Congress has not legislated in the area. However, this freedom can be lost if Congress passes legislation restraining such judicial activism. Justice David Souter delivered the opinion of the Court.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"FCC v. League of Women Voters of Cal.","cite":"468 U.S. 364","y":1984,"id":"1983/82-912","sc":1,"op":2,"ar":1,"sum":"Even though the Commerce Clause gives Congress the power to regulate the broadcast medium, \"since broadcasters are engaged in a vital and independent form of communicative activity,\" Congress must use the First Amendment to \"inform and give shape\" to its regulation.","sumSrc":"Oyez","by":{"0":"12, 24, 35","2":"22","3":"7"}},{"t":"case","label":"Foman v. Davis","cite":"371 U.S. 178","y":1962,"id":"1962/41","sc":1,"op":1,"sum":"A Federal District Court dismissed petitioner's complaint in a civil action for failure to state a claim upon which relief might be granted. Petitioner promptly moved to vacate the judgment and amend the complaint so as to state an alternative theory for recovery. Before the Court ruled on those motions, petitioner filed notice of appeal from the judgment of dismissal. Subsequently, the District Court denied the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Garcia v. Superintendent of Great Meadow Corr. Facility","cite":"841 F.3d 581","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/841/581/","by":{"0":"42"}},{"t":"case","label":"Gonzalez v. Crosby","cite":"545 U.S. 524","y":2005,"id":"2004/04-6432","sc":1,"op":11,"sum":"In 7-2 opinion delivered by Justice Antonin Scalia, the Court held that Gonzalez's Rule 60(b) motion challenged only the district court's previous ruling on the federal statute of limitations. That motion was therefore not the equivalent of a successive habeas petition and could be ruled on by the district court without the 11th Circuit's precertification.","sumSrc":"Oyez","by":{"0":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Gonzalez v. Secretary for Dep’t of Corr.","cite":"317 F.3d 1308","y":2003,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/317/1308/","by":{"0":"29","3":"9"}},{"t":"case","label":"Greene v. Fisher","cite":"565 U.S. 34","y":2011,"id":"2011/10-637","sc":1,"sum":"The Court held that decisions of the Court do not constitute \"clearly established federal law\" if the decision predates the decision of a relevant state court.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Howard v. United States","cite":"533 F.3d 472","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/533/472/","by":{"0":"3, 37, 42, 43, 44","2":"15","3":"4"}},{"t":"case","label":"Inglese v. Warden, U.S. Penitentiary","cite":"687 F.2d 362","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/687/362/","by":{"0":"26"}},{"t":"case","label":"Johnson v. United States","cite":"196 F.3d 802","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/196/802/","by":{"0":"20, 21, 34","2":"21","3":"16"}},{"t":"case","label":"Jones v. Cunningham","cite":"371 U.S. 236","y":1963,"id":"1962/77","sc":1,"sum":"1. A state prisoner who has been placed on parole, under the \"custody and control\" of a parole board, is \"in custody\" within the meaning of 28 U. S. C. § 2241; and, on his petition for a writ of habeas corpus, a Federal District. Court has jurisdiction to hear and determihe his charge that his state sentence was imposed in violation of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Kuhlmann v. Wilson","cite":"477 U.S. 436","y":1986,"id":"1985/84-1479","sc":1,"op":3,"sum":"The judgment is reversed, and the case is remanded. 742 F. 2d 741, reversed and remanded. JUSTICE POWELL delivered the opinion of the Court with respect to Parts I, IV, and V, concluding that the Court of Appeals erred in holding that respondent was entitled to relief under United States v. Henry, supra, which left open the question whether the Sixth Amendment forbids admission in evidence of an accused's statements …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 26","2":"17"}},{"t":"case","label":"Littlejohn v. Artuz","cite":"271 F.3d 360","y":2001,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/271/360/","by":{"0":"20"}},{"t":"case","label":"Lomax v. Armontrout","cite":"923 F.2d 574","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/923/574/","by":{"0":"26"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"op":3,"ar":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"0":"16, 18, 20","3":"4, 5"}},{"t":"case","label":"Mayle v. Felix","cite":"545 U.S. 644","y":2005,"id":"2004/04-563","sc":1,"op":9,"sum":"The Court rejected the argument that the trial itself was the \"transaction\" or \"occurrence\" under federal habeas law. The Court said that such a definition would have allowed virtually any new claim introduced in an amended petition to relate back, gutting the one-year time limit on petitions.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"op":1,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17, 18","2":"16"}},{"t":"case","label":"Midatlantic Nat’l Bank v. New Jersey Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Miller-El v. Cockrell","cite":"537 U.S. 322","y":2003,"id":"2002/01-7662","sc":1,"op":1,"sum":"The Court held that the Court of Appeals should have issued a COA to review the District Court's denial of habeas corpus relief.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Mississippi ex rel. Hood v. AU Optronics Corp.","cite":"571 U.S. 161","y":2014,"id":"2013/12-1036","sc":1,"sum":"The Court ruled that, in order for a case to be removed to a federal district court instead of a state court under the Class Action Fairness Act, at least 100 people must be represented by the lawsuit.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Ochoa v. Sirmons","cite":"485 F.3d 538","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/485/538/","by":{"0":"42"}},{"t":"case","label":"Osterneck v. Ernst & Whinney","cite":"489 U.S. 169","y":1989,"id":"1988/87-1201","sc":1,"op":3,"sum":"Petitioners' motion for prejudgment interest constituted a Rule 59(e) motion and rendered ineffective under Rule 4(a)(4) their notice of appeal filed before a ruling on that motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 39"}},{"t":"case","label":"Panetti v. Quarterman","cite":"551 U.S. 930","y":2007,"id":"2006/06-6407","sc":1,"op":4,"sum":"Stating that the phrase “takes its full meaning from our case law”.","sumSrc":"opinion","by":{"0":"13, 19, 20, 32, 39","2":"27","3":"3, 5, 7"}},{"t":"case","label":"Parkus v. Delo","cite":"985 F.3d 425","y":1993,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/985/425/","by":{"0":"26"}},{"t":"case","label":"Rishor v. Ferguson","cite":"822 F.3d 482","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/822/482/","by":{"0":"37, 42, 43, 47","3":"17"}},{"t":"case","label":"Salinger v. Loisel","cite":"265 U.S. 224","y":1924,"id":"scdb/1923-152","sc":1,"sum":"1. Warrants of removal issued in triplicate are in legal effect but a single warrant, and defendant who had secured a supersedeas on appeal from an order refusing relief by habeas corpus from arrest under one, could not lawfully be arrested under another.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"op":1,"sum":"The Court should have granted a hearing on the second motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18","2":"17"}},{"t":"case","label":"Schlup v. Delo","cite":"513 U.S. 298","y":1995,"id":"1994/93-7901","sc":1,"sum":"Petitioner Schlup, a Missouri prisoner, was convicted of participating in the murder of a fellow inmate and sentenced to death. In this, his second federal habeas petition, he alleged that constitutional error at his trial deprived the jury of critical evidence that would have established his innocence. The District Court declined to reach the petition's merits, holding that Schlup could not satisfy the threshold …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Slack v. McDaniel","cite":"529 U.S. 473","y":2000,"id":"1999/98-6322","sc":1,"op":4,"sum":"The Court held that a federal habeas corpus petition filed by a state prisoner, after an initial petition was dismissed without adjudication on the merits, does not constitute a \"second or successive\" petition, subject to dismissal for abuse of writ.","sumSrc":"Oyez","by":{"0":"19, 27"}},{"t":"case","label":"Spencer v. Kemna","cite":"523 U.S. 1","y":1998,"id":"1997/96-7171","sc":1,"sum":"The Court held that the expiration of Spencer's sentence caused his petition to be moot because it no longer presented an Article III case or controversy. The Court concluded that once a petitioner's sentence has expired he must demonstrate a concrete and continuing injury to maintain suit.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Stewart v. v. Martinez-Villareal","cite":"523 U.S. 637","y":1998,"id":"1997/97-300","sc":1,"op":2,"sum":"Announced by Chief Justice William H. Rehnquist, the Court ruled Martinez-Villareal cannot be barred from raising his incompetency claim in a successive petition because his claim was really amended.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"op":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 31"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Grp. Brands LLC","cite":"137 S. Ct. 1514","y":2017,"id":"2016/16-341","sc":1,"op":1,"sum":"The Court held that the subsection of the general venue statute that allows a corporation to reside in many jurisdictions for the purpose of establishing jurisdiction does not apply to the patent venue statute.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"op":2,"sum":"The judgment is affirmed. 820 F. 2d 832, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, and III, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"United States v. Evans","cite":"2015 WL 2169503","y":2015,"court":"E.D. Va. May 8","by":{"0":"40"}},{"t":"case","label":"United States v. Ibarra","cite":"502 U.S. 1","y":1991,"id":"1991/90-1713","sc":1,"op":1,"sum":"Noting that giving district courts a short time to correct their own errors “prevents unnecessary burdens being placed on the courts of appeals”.","sumSrc":"opinion","by":{"0":"13, 39, 50, 51","3":"18"}},{"t":"case","label":"United States v. Pedraza","cite":"466 F.3d 932","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/466/932/","by":{"0":"28"}},{"t":"case","label":"United States v. Santarelli","cite":"929 F.3d 95","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/929/95/","by":{"0":"20, 21, 42"}},{"t":"case","label":"United States v. Sellner","cite":"773 F.3d 927","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/773/927/","by":{"0":"20, 21"}},{"t":"case","label":"United States v. Trent","cite":"884 F.3d 985","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/884/985/","by":{"0":"20"}},{"t":"case","label":"Vitko v. United States","cite":"2016 WL 2930909","y":2016,"court":"D. Me. May 19","by":{"0":"40"}},{"t":"case","label":"Ward v. Norris","cite":"577 F.3d 925","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/577/925/","by":{"0":"28"}},{"t":"case","label":"White v. New Hampshire Dep’t of Emp’t Sec.","cite":"455 U.S. 445","y":1982,"id":"1981/80-5887","sc":1,"op":3,"sum":"Rule 59(e) is not applicable to postjudgment requests for attorney's fees under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 23, 25, 37, 48","3":"4, 17"}},{"t":"case","label":"Williams v. Thaler","cite":"602 F.3d 291","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/602/291/","by":{"0":"28, 30, 46"}},{"t":"case","label":"Wilson v. Ozmint","cite":"357 F.3d 461","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/357/461/","sum":"Noting that, because the mandate had not issued in a habeas appeal, the court could, “at [its] discretion, amend what [it] previously decided” (quotation marks omitted).","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"Wong Doo v. United States","cite":"265 U.S. 239","y":1924,"id":"scdb/1923-153","sc":1,"sum":"1. Thg strict -doctrine of res judieoato does not apply to habeascorpus. Salinger v. Loisel, cte, 224.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Woods v. Carey","cite":"525 F.3d 886","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/525/886/","by":{"0":"21"}},{"t":"case","label":"Zimmerman v. United States","cite":"298 U.S. 167","y":1936,"id":"scdb/1935-063","sc":1,"op":1,"sum":"An order made by a district judge on his own motion during the term at which a decree has been entered, reciting the need for an amendment of the decree and extending the term to a future day for the declared purpose of allowing such amendment, without specifying the change in contemplation, has the effect of suspending the operation of the decree so that no appeal can be taken from it until it has been amended or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","3":"3"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"1","2":"3"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)","(b)(1)","(b)(2)","(b)(3)","(d)","(1958)","(b)(2)(A)","(b)(2)(B)(ii)","(b)(3)(A)","(b)(3)(B)","(b)(3)(C)","(b)(3)(E)","(b)(4)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":1,"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, passim, passim, 19, 37, 19, 35, 38, 43","2":"16, passim, 4, 9, 10, 10, 4, 4, 3, 8, 10, 27, 4, 4, 27, 20, 4","3":"passim, 10, 13, 19, 14"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","subs":["(c)","(a)","(c)(2)"],"stext":{"head":"§2253. Appeal","paras":[[0,"(a) In a habeas corpus proceeding or a proceeding under section 2255 before a district judge, the final order shall be subject to review, on appeal, by the court of appeals for the circuit in which the proceeding is held."],[0,"(b) There shall be no right of appeal from a final order in a proceeding to test the validity of a warrant to remove to another district or place for commitment or trial a person charged with a criminal offense against the United States, or to test the validity of such person's detention pending removal proceedings."],[0,"(c)(1) Unless a circuit justice or judge issues a certificate of appealability, an appeal may not be taken to the court of appeals from—"],[1,"(A) the final order in a habeas corpus proceeding in which the detention complained of arises out of process issued by a State court; or"],[1,"(B) the final order in a proceeding under section 2255."],[0,"(2) A certificate of appealability may issue under paragraph (1) only if the applicant has made a substantial showing of the denial of a constitutional right."],[0,"(3) The certificate of appealability under paragraph (1) shall indicate which specific issue or issues satisfy the showing required by paragraph (2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2253?type=usc&year=mostrecent&link-type=html"},"head":"§2253. Appeal","tname":"Judiciary and Judicial Procedure","by":{"0":"33, 41, 46","2":"5, 23, 24, 8, 23, 5, 8, 14, 5, 22","3":"23"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(d)","(b)(1)(A)","(c)"],"stext":{"head":"§2254. State custody; remedies in Federal courts","paras":[[0,"(a) The Supreme Court, a Justice thereof, a circuit judge, or a district court shall entertain an application for a writ of habeas corpus in behalf of a person in custody pursuant to the judgment of a State court only on the ground that he is in custody in violation of the Constitution or laws or treaties of the United States."],[0,"(b)(1) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted unless it appears that—"],[1,"(A) the applicant has exhausted the remedies available in the courts of the State; or"],[1,"(B)(i) there is an absence of available State corrective process; or"],[1,"(ii) circumstances exist that render such process ineffective to protect the rights of the applicant."],[0,"(2) An application for a writ of habeas corpus may be denied on the merits, notwithstanding the failure of the applicant to exhaust the remedies available in the courts of the State."],[0,"(3) A State shall not be deemed to have waived the exhaustion requirement or be estopped from reliance upon the requirement unless the State, through counsel, expressly waives the requirement."],[0,"(c) An applicant shall not be deemed to have exhausted the remedies available in the courts of the State, within the meaning of this section, if he has the right under the law of the State to raise, by any available procedure, the question presented."],[0,"(d) An application for a writ of habeas corpus on behalf of a person in custody pursuant to the judgment of a State court shall not be granted with respect to any claim that was adjudicated on the merits in State court proceedings unless the adjudication of the claim—"],[1,"(1) resulted in a decision that was contrary to, or involved an unreasonable application of, clearly established Federal law, as determined by the Supreme Court of the United States; or"],[1,"(2) resulted in a decision that was based on an unreasonable determination of the facts in light of the evidence presented in the State court proceeding."],[0,"(e)(1) In a proceeding instituted by an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court, a determination of a factual issue made by a State court shall be presumed to be correct. The applicant shall have the burden of rebutting the presumption of correctness by clear and convincing evidence."],[0,"(2) If the applicant has failed to develop the factual basis of a claim in State court proceedings, the court shall not hold an evidentiary hearing on the claim unless the applicant shows that—"],[1,"(A) the claim relies on—"],[2,"(i) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[2,"(ii) a factual predicate that could not have been previously discovered through the exercise of due diligence; and"],[1,"(B) the facts underlying the claim would be sufficient to establish by clear and convincing evidence that but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(f) If the applicant challenges the sufficiency of the evidence adduced in such State court proceeding to support the State court's determination of a factual issue made therein, the applicant, if able, shall produce that part of the record pertinent to a determination of the sufficiency of the evidence to support such determination. If the applicant, because of indigency or other reason is unable to produce such part of the record, then the State shall produce such part of the record and the Federal court shall direct the State to do so by order directed to an appropriate State official. If the State cannot provide such pertinent part of the record, then the court shall determine under the existing facts and circumstances what weight shall be given to the State court's factual determination."],[0,"(g) A copy of the official records of the State court, duly certified by the clerk of such court to be a true and correct copy of a finding, judicial opinion, or other reliable written indicia showing such a factual determination by the State court shall be admissible in the Federal court proceeding."],[0,"(h) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel for an applicant who is or becomes financially unable to afford counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(i) The ineffectiveness or incompetence of counsel during Federal or State collateral post-conviction proceedings shall not be a ground for relief in a proceeding arising under section 2254."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2254?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2254. State custody; remedies in Federal courts","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, 38","2":"2, 3, 10, 26, 3, 3","3":"14, 18, 22, 19, 21, 7"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 2266","url":"https://www.law.cornell.edu/uscode/text/28/2266","subs":["(c)(1)(B)","(b)","(b)(1)(A)","(b)(1)(B)","(b)(1)(C)","(c)(1)(A)","(c)(1)(B)(i)","(c)(1)(B)(ii)","(c)","(c)(1)"],"stext":{"head":"§2266. Limitation periods for determining applications and motions","paras":[[0,"(a) The adjudication of any application under section 2254 that is subject to this chapter, and the adjudication of any motion under section 2255 by a person under sentence of death, shall be given priority by the district court and by the court of appeals over all noncapital matters."],[0,"(b)(1)(A) A district court shall render a final determination and enter a final judgment on any application for a writ of habeas corpus brought under this chapter in a capital case not later than 450 days after the date on which the application is filed, or 60 days after the date on which the case is submitted for decision, whichever is earlier."],[0,"(B) A district court shall afford the parties at least 120 days in which to complete all actions, including the preparation of all pleadings and briefs, and if necessary, a hearing, prior to the submission of the case for decision."],[0,"(C)(i) A district court may delay for not more than one additional 30-day period beyond the period specified in subparagraph (A), the rendering of a determination of an application for a writ of habeas corpus if the court issues a written order making a finding, and stating the reasons for the finding, that the ends of justice that would be served by allowing the delay outweigh the best interests of the public and the applicant in a speedy disposition of the application."],[0,"(ii) The factors, among others, that a court shall consider in determining whether a delay in the disposition of an application is warranted are as follows:"],[1,"(I) Whether the failure to allow the delay would be likely to result in a miscarriage of justice."],[1,"(II) Whether the case is so unusual or so complex, due to the number of defendants, the nature of the prosecution, or the existence of novel questions of fact or law, that it is unreasonable to expect adequate briefing within the time limitations established by subparagraph (A)."],[1,"(III) Whether the failure to allow a delay in a case that, taken as a whole, is not so unusual or so complex as described in subclause (II), but would otherwise deny the applicant reasonable time to obtain counsel, would unreasonably deny the applicant or the government continuity of counsel, or would deny counsel for the applicant or the government the reasonable time necessary for effective preparation, taking into account the exercise of due diligence."],[0,"(iii) No delay in disposition shall be permissible because of general congestion of the court's calendar."],[0,"(iv) The court shall transmit a copy of any order issued under clause (i) to the Director of the Administrative Office of the United States Courts for inclusion in the report under paragraph (5)."],[0,"(2) The time limitations under paragraph (1) shall apply to—"],[1,"(A) an initial application for a writ of habeas corpus;"],[1,"(B) any second or successive application for a writ of habeas corpus; and"],[1,"(C) any redetermination of an application for a writ of habeas corpus following a remand by the court of appeals or the Supreme Court for further proceedings, in which case the limitation period shall run from the date the remand is ordered."],[0,"(3)(A) The time limitations under this section shall not be construed to entitle an applicant to a stay of execution, to which the applicant would otherwise not be entitled, for the purpose of litigating any application or appeal."],[0,"(B) No amendment to an application for a writ of habeas corpus under this chapter shall be permitted after the filing of the answer to the application, except on the grounds specified in section 2244(b)."],[0,"(4)(A) The failure of a court to meet or comply with a time limitation under this section shall not be a ground for granting relief from a judgment of conviction or sentence."],[0,"(B) The State may enforce a time limitation under this section by petitioning for a writ of mandamus to the court of appeals. The court of appeals shall act on the petition for a writ of mandamus not later than 30 days after the filing of the petition."],[0,"(5)(A) The Administrative Office of the United States Courts shall submit to Congress an annual report on the compliance by the district courts with the time limitations under this section."],[0,"(B) The report described in subparagraph (A) shall include copies of the orders submitted by the district courts under paragraph (1)(B)(iv)."],[0,"(c)(1)(A) A court of appeals shall hear and render a final determination of any appeal of an order granting or denying, in whole or in part, an application brought under this chapter in a capital case not later than 120 days after the date on which the reply brief is filed, or if no reply brief is filed, not later than 120 days after the date on which the answering brief is filed."],[0,"(B)(i) A court of appeals shall decide whether to grant a petition for rehearing or other request for rehearing en banc not later than 30 days after the date on which the petition for rehearing is filed unless a responsive pleading is required, in which case the court shall decide whether to grant the petition not later than 30 days after the date on which the responsive pleading is filed."],[0,"(ii) If a petition for rehearing or rehearing en banc is granted, the court of appeals shall hear and render a final determination of the appeal not later than 120 days after the date on which the order granting rehearing or rehearing en banc is entered."],[0,"(2) The time limitations under paragraph (1) shall apply to—"],[1,"(A) an initial application for a writ of habeas corpus;"],[1,"(B) any second or successive application for a writ of habeas corpus; and"],[1,"(C) any redetermination of an application for a writ of habeas corpus or related appeal following a remand by the court of appeals en banc or the Supreme Court for further proceedings, in which case the limitation period shall run from the date the remand is ordered."],[0,"(3) The time limitations under this section shall not be construed to entitle an applicant to a stay of execution, to which the applicant would otherwise not be entitled, for the purpose of litigating any application or appeal."],[0,"(4)(A) The failure of a court to meet or comply with a time limitation under this section shall not be a ground for granting relief from a judgment of conviction or sentence."],[0,"(B) The State may enforce a time limitation under this section by applying for a writ of mandamus to the Supreme Court."],[0,"(5) The Administrative Office of the United States Courts shall submit to Congress an annual report on the compliance by the courts of appeals with the time limitations under this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2266?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2266. Limitation periods for determining applications and motions","tname":"Judiciary and Judicial Procedure","by":{"0":"35","2":"24, 25, 8, 24, 24, 25, 25, 25, 24, 24, 24, 8, 24","3":"14, 14"}},{"t":"case","label":"Aderhold v. Murphy","cite":"103 F.2d 492","y":1939,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/103/492/","op":1,"by":{"2":"20"}},{"t":"case","label":"Bur ton v. Stewart","cite":"549 U.S. 147","y":2007,"id":"2006/05-9222","sc":1,"op":1,"sum":"In a 9-0 per curiam opinion, the Court ruled that Burton's habeas petition should be dismissed for lack of jurisdiction. Burton had earlier filed a habeas petition challenging his conviction. Four years later, when he filed the habeas petition challenging only his sentence, Burton neglected to obtain the court authorization necessary for a \"second or successive\" petition.","sumSrc":"Oyez","by":{"2":"4, 8, 27"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"op":1,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"2":"3, 18","3":"6"}},{"t":"case","label":"Hamer v. Neighborhood Housing Servs.","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"op":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Rhines v. Weber","cite":"544 U.S. 269","y":2005,"id":"2004/03-9046","sc":1,"op":2,"sum":"The Court held that a district court could stay a mixed petition to allow a petitioner to present unexhausted claims in state court and then return to federal court.","sumSrc":"Oyez","by":{"2":"10, 16, 21"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Strickland v. Washington","cite":"466 U.S. 668","y":1984,"id":"1983/82-1554","sc":1,"sum":"The Supreme Court held that: (1) counsel's performance must be deficient; and (2) the deficient performance must have prejudiced the defense so as to deprive the defendant of a fair trial.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Tiberg v. Warren","cite":"192 F. 458","y":1911,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F./192/458/","op":1,"by":{"2":"20"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"op":1,"sum":"The Court held that under federal law, as amended by the AEDPA, \"a 'failure to develop' a claim's factual basis in state court proceedings is not established unless there is lack of diligence, or some greater fault, attributable to the prisoner or his counsel.\" Justice Kennedy wrote for the Court that \"comity is not served by saying a prisoner 'has failed to develop the factual basis of a claim' where he was unable to develop his claim in state court despite diligent effort.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Woodford v. Garceau","cite":"538 U.S. 202","y":2003,"id":"2002/01-1862","sc":1,"sum":"The Court held, for purposes of Lindh, that a case does not become \"pending\" until an actual application for habeas corpus relief is filed in federal court.","sumSrc":"Oyez","by":{"2":"10, 16"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"2":"14, 22"}},{"t":"usc","label":"28 U.S.C. § 2107","url":"https://www.law.cornell.edu/uscode/text/28/2107","stext":{"head":"§2107. Time for appeal to court of appeals","paras":[[0,"(a) Except as otherwise provided in this section, no appeal shall bring any judgment, order or decree in an action, suit or proceeding of a civil nature before a court of appeals for review unless notice of appeal is filed, within thirty days after the entry of such judgment, order or decree."],[0,"(b) In any such action, suit, or proceeding, the time as to all parties shall be 60 days from such entry if one of the parties is—"],[1,"(1) the United States;"],[1,"(2) a United States agency;"],[1,"(3) a United States officer or employee sued in an official capacity; or"],[1,"(4) a current or former United States officer or employee sued in an individual capacity for an act or omission occurring in connection with duties performed on behalf of the United States, including all instances in which the United States represents that officer or employee when the judgment, order, or decree is entered or files the appeal for that officer or employee."],[0,"(c) The district court may, upon motion filed not later than 30 days after the expiration of the time otherwise set for bringing appeal, extend the time for appeal upon a showing of excusable neglect or good cause. In addition, if the district court finds—"],[1,"(1) that a party entitled to notice of the entry of a judgment or order did not receive such notice from the clerk or any party within 21 days of its entry, and"],[1,"(2) that no party would be prejudiced,"],[0,"the district court may, upon motion filed within 180 days after entry of the judgment or order or within 14 days after receipt of such notice, whichever is earlier, reopen the time for appeal for a period of 14 days from the date of entry of the order reopening the time for appeal."],[0,"(d) This section shall not apply to bankruptcy matters or other proceedings under Title 11."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2107?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2107. Time for appeal to court of appeals","tname":"Judiciary and Judicial Procedure","by":{"2":"5"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(h)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"2":"1, 1"}},{"t":"usc","label":"28 U.S.C. § 2261","url":"https://www.law.cornell.edu/uscode/text/28/2261","by":{"2":"24"}},{"t":"case","label":"Banister v. Davis","cite":"139 S. Ct. 2742","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./139/2742/","sc":1,"by":{"3":"12"}},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"sum":"The Court held that the Commissioner's initial assignments made after October 1, 1993, are valid despite their untimeliness. The Court reasoned that a statute directing official action needed more than a mandatory \"shall\" before the grant of power would be read to expire when the job was supposed to be completed.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"Charles v. Daley","cite":"799 F.2d 343","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/799/343/","by":{"3":"11"}},{"t":"case","label":"Correll v. Thompson","cite":"63 F.3d 1279","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/63/1279/","sum":"Finding no procedural error in district court’s use of Rule 59(e) to vacate its prior decision, but reversing on the merits.","sumSrc":"brief:3","by":{"3":"6"}},{"t":"case","label":"Gibbs v. Maxwell House","cite":"701 F.2d 145","y":1983,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/701/145/","by":{"3":"11"}},{"t":"case","label":"Griggs v. Provident Consumer Disc. Co.","cite":"459 U.S. 56","y":1982,"id":"1982/82-5082","sc":1,"sum":"The Court of Appeals' analysis of Rule 4(a)(4) is contrary to the language and purposes of the 1979 amendments to the Rules of Appellate Procedure. Prior to 1979, if a notice of appeal was fied pending disposition of a motion to vacate, alter, or amend the judgment it was generally held that the district court retained jurisdiction to decide the motion and the notice of appeal was adequate for purposes of beginning …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"10"}},{"t":"case","label":"Kremer v. Chemical Constr. Corp.","cite":"456 U.S. 461","y":1982,"id":"1981/80-6045","sc":1,"sum":"The District Court was required under 28 U. S. C. § 1738 to give preclusive effect to the state court decision upholding the state administrative agency's rejection of the employment discrimination claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"Laber v. Harvey","cite":"438 F.3d 404","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/438/404/","by":{"3":"16"}},{"t":"case","label":"Martin v. Singletary","cite":"965 F.2d 944","y":1992,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/965/944/","by":{"3":"15"}},{"t":"case","label":"Morse v. United States","cite":"270 U.S. 151","y":1926,"id":"scdb/1925-069","sc":1,"ar":1,"by":{"3":"21"}},{"t":"case","label":"Moy v. Howard Univ.","cite":"843 F.2d 1504","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/843/1504/","by":{"3":"11"}},{"t":"case","label":"Phillips v. United States","cite":"668 F.3d 433","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/668/433/","by":{"3":"16"}},{"t":"case","label":"Skagerberg v. Oklahoma","cite":"797 F.2d 881","y":1986,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/797/881/","op":1,"by":{"3":"11"}},{"t":"case","label":"Stanhope v. Ryan","cite":"2015 WL 1013716","y":2015,"court":"D. Ariz. Mar. 9","by":{"3":"23"}},{"t":"case","label":"United States v. Dieter","cite":"429 U.S. 6","y":1976,"id":"1976/75-1547","sc":1,"sum":"The 30-day limitation period prescribed by the Criminal Appeals Act and Fed. Rule App. Proc. 4 (b) for a Government appeal from an order dismissing an indictment ran from the date of the District Court's denial of the Government's motion to set aside the dismissal of the indictment against respondent, rather than from the date of the dismissal order, and hence the Government's appeal was timely where its notice of …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"op":1,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"United States v. Nelson","cite":"465 F.3d 1145","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/1145/","by":{"3":"17"}},{"t":"case","label":"York v. Tate","cite":"858 F.2d 322","y":1988,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/858/322/","op":1,"by":{"3":"6"}}]};